-- MERCHY — Tablas de precio reales por técnica (proporcionadas por el
-- usuario, transcritas y verificadas -- no se inventó ni interpoló ningún
-- valor). Ejecutar en: Supabase Dashboard → SQL Editor
--
-- Agrega pricing_type (arquitectura por técnica -- cada técnica define su
-- propio parámetro):
--   'by_qty'    -> price_table: [{qty_min, qty_max, price_per_element}]      (sin cambio, ej. DTG)
--   'by_tintas' -> price_table: [{tintas, qty_min, qty_max, price_per_element}]
--   'by_size'   -> price_table: [{size, qty_min, qty_max, price_per_element}]
--   NULL        -> sin datos suficientes todavía -> "Precio por cotizar"

ALTER TABLE print_techniques ADD COLUMN IF NOT EXISTS pricing_type TEXT;

